class Stack:
    """Thin wrapper around list to make intent explicit."""

    def __init__(self):
        self._data = []

    def push(self, item):
        self._data.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self._data.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError("peek from empty stack")
        return self._data[-1]

    def is_empty(self):
        return len(self._data) == 0

    def __len__(self):
        return len(self._data)

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

# factorial(3) call stack at deepest point:
# | factorial(0) |  ← top of call stack
# | factorial(1) |
# | factorial(2) |
# | factorial(3) |  ← first frame pushed
# | __main__     |  ← bottom

class CircularBuffer:
    def __init__(self, capacity):
        self._buf = [None] * capacity
        self._cap = capacity
        self._head = 0   # front (dequeue here)
        self._tail = 0   # rear  (enqueue here)
        self._size = 0

    def enqueue(self, item):
        if self._size == self._cap:
            raise OverflowError("buffer full")
        self._buf[self._tail] = item
        self._tail = (self._tail + 1) % self._cap
        self._size += 1

    def dequeue(self):
        if self._size == 0:
            raise IndexError("buffer empty")
        item = self._buf[self._head]
        self._head = (self._head + 1) % self._cap
        self._size -= 1
        return item

def is_balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return len(stack) == 0

print(is_balanced("({[]})"))  # True
print(is_balanced("({)}"))    # False

from collections import deque

def bfs_levels(graph, start):
    queue = deque([start])
    visited = {start}
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

undo_stack = []  # actions performed
redo_stack = []  # actions undone

def do(action):
    action.execute()
    undo_stack.append(action)
    redo_stack.clear()  # new action invalidates redo history

def undo():
    if undo_stack:
        action = undo_stack.pop()
        action.reverse()
        redo_stack.append(action)

def redo():
    if redo_stack:
        action = redo_stack.pop()
        action.execute()
        undo_stack.append(action)
